import{_ as t,a as s}from"./chunks/description-1.Hseqjb9Z.js";import{_ as n,o as r,c as i,a5 as e}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"배터리 취급 주의사항","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/battery-handling.md","filePath":"ko/manual/safety/battery-handling.md","lastUpdated":1787021357000}'),o={name:"ko/manual/safety/battery-handling.md"};function l(c,a,d,p,g,h){return r(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="배터리-취급-주의사항" tabindex="-1">배터리 취급 주의사항 <a class="header-anchor" href="#배터리-취급-주의사항" aria-label="Permalink to &quot;배터리 취급 주의사항&quot;">​</a></h1><p>RBQ에 탑재된 배터리의 안전한 취급·충전·보관에 관한 주의사항입니다. 실제 교체 절차는 <a href="/RBQ/nightly/ko/manual/maintenance/battery.html">배터리 교체</a>를 참고하세요.</p><h2 id="충전" tabindex="-1">충전 <a class="header-anchor" href="#충전" aria-label="Permalink to &quot;충전&quot;">​</a></h2><figure><img src="'+t+'" alt="RBQ10 전용 충전기로 충전하는 예"><img src="'+s+'" alt="RBQ10 전용 도킹 스테이션으로 충전하는 예"><figcaption style="text-align:center;">[ 지정 충전기·도킹 스테이션으로만 충전하세요 ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>1) 반드시 RBQ10 전용 충전기 또는 RBQ10 도킹 스테이션으로만 충전하세요. 다른 충전기는 과충전·과열·화재의 원인이 됩니다.<br>2) 충전 중에는 로봇과 충전기를 가연성 물질이나 열원에서 멀리 두세요.<br>3) 충전기·케이블이 손상되었으면 사용하지 마세요.</p></div></div><p>충전 방법 및 절차는 <a href="/RBQ/nightly/ko/manual/operation/charging.html">충전</a> 페이지를 참고하세요.</p><ul><li><strong>완전 방전 시</strong>: 로봇이 완전히 방전되어 전원이 켜지지 않으면 도킹 스테이션으로는 충전이 되지 않을 수 있습니다. 이 경우 제공된 외부 충전기로 충전 포트에 직접 연결해 충전하세요.</li></ul><h2 id="취급·보관" tabindex="-1">취급·보관 <a class="header-anchor" href="#취급·보관" aria-label="Permalink to &quot;취급·보관&quot;">​</a></h2><ul><li><strong>충격·침투</strong>: 배터리를 떨어뜨리거나 구멍을 내거나 물에 담그지 마세요. 손상된 배터리는 사용하지 말고 Rainbow Robotics에 문의하세요.</li><li><strong>온도</strong>: 규정된 보관·사용 온도 범위를 지키세요. 고온·직사광선·난로 부근에 두지 마세요.</li><li><strong>보관</strong>: 배터리를 뒤집어서 보관하지 마세요. 장기간 사용하지 않을 때는 주기적으로 상태를 확인하세요.</li></ul><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p><strong>미사용 시 배터리 분리</strong>: 사용하지 않을 때는 <strong>배터리를 분리</strong>하여 보관하세요. 전원이 꺼진 로봇에 <strong>24시간 이상</strong> 배터리를 꽂아 두면 <strong>회복 불가능한 손상</strong>이 발생할 수 있습니다.</p></div></div>',10)])])}const _=n(o,[["render",l]]);export{b as __pageData,_ as default};
